$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$Stage='D:\Claude\swiftright\.factory-work\hosts\custom-layout-observation';$Requests=Join-Path $Stage 'requests-final-r1'
if(@(Get-Process swift,swiftc,swift-build,clang,FactoryProbe -ErrorAction SilentlyContinue).Count){throw 'compiler/native lane busy'}
if(Test-Path -LiteralPath $Requests){throw 'fresh final requests required'}
New-Item -ItemType Directory -Path $Requests|Out-Null
$Rows='[{"path":"plan-prebuild-v4.json","bytes":11442,"sha256":"41585a5223083d771bfce4be0436141b5469037253604de772a81eea70f97a6d","base64":""},{"path":"build-owned-pilot-v1.ps1","bytes":11163,"sha256":"10ff142aa01057459dc7507e41e25f8c5141b37ff8ceb40268f3ef251e3cc565","base64":""},{"path":"plan-final-v4.json","bytes":40628,"sha256":"aba099eb6981b2c4dce30194584c19b7b298bc05d82b01e83a64f7ff4eaa894c","base64":""},{"path":"build-owned-final-v1.ps1","bytes":11159,"sha256":"c471806db7771ea1585e126808570867a513f1bf91e497f818cc80836b6962f3","base64":""},{"path":"final-remote-entry.ps1","bytes":3093,"sha256":"1433d39c2ecc1d588958b99a2be40110e86d7dce5cf5fc444d000a6203d89544","base64":""}]'|ConvertFrom-Json
foreach($Row in @($Rows)){
  $P=Join-Path $Requests $Row.path
  [IO.File]::WriteAllBytes($P,[Convert]::FromBase64String($Row.base64))
  $I=Get-Item -LiteralPath $P
  if($I.Length -ne $Row.bytes -or (Get-FileHash -LiteralPath $P).Hash.ToLowerInvariant() -cne $Row.sha256){throw 'staged finalized source drift'}
}
& (Join-Path $Requests 'final-remote-entry.ps1') -PreflightOnly
& (Join-Path $Requests 'final-remote-entry.ps1')
$R=Join-Path $Stage 'final-r1\observation.json'
